pub fn policy_partition_assignment_over(
    modules: Rc<Vec<NonEmptyStr>>,
    components: Rc<Vec<Rc<Vec<String>>>>,
    policy: PartitionPolicy,
) -> Rc<HashMap<NonEmptyStr, NonEmptyStr>> {
    {
        let quota = v1_rt::int_div(
            v1_rt::int_sub(
                v1_rt::int_add(
                    (modules.clone().len() as i64),
                    policy.target_crate_count.clone(),
                ),
                1,
            ),
            policy.target_crate_count.clone(),
        );
        let filled = components.iter().cloned().fold(
            Rc::new(PolicyPartitionFill {
                assignment: v1_rt::rc_empty_map::<NonEmptyStr, NonEmptyStr>(),
                unit_index: 0,
                filled: 0,
            }),
            |acc: Rc<PolicyPartitionFill>, component: Rc<Vec<String>>| {
                let opens_next_unit = ((acc.filled.clone() >= quota.clone())
                    && (v1_rt::int_add(acc.unit_index.clone(), 1)
                        < policy.target_crate_count.clone()));
                let unit_index = if opens_next_unit.clone() {
                    v1_rt::int_add(acc.unit_index.clone(), 1)
                } else {
                    acc.unit_index.clone()
                };
                let already = if opens_next_unit.clone() {
                    0
                } else {
                    acc.filled.clone()
                };
                let unit_id = policy_partition_unit_id(unit_index.clone());
                Rc::new(PolicyPartitionFill {
                    assignment: component.iter().cloned().fold(
                        acc.assignment.clone(),
                        |inner: Rc<HashMap<NonEmptyStr, NonEmptyStr>>, member: String| {
                            v1_rt::rc_map_insert(inner, member.clone(), unit_id.clone())
                        },
                    ),
                    unit_index: unit_index.clone(),
                    filled: v1_rt::int_add(already.clone(), (component.clone().len() as i64)),
                })
            },
        );
        filled.assignment.clone()
    }
}

